def main():
    narada_list = []
    for s in NARADA_SUTRAS:
        narada_list.append({
            "sutra_no": str(s[0]),
            "sanskrit": s[1],
            "theme": s[2],
            "initial_meaning": {
                "en": s[3],
                "hi": s[4],
                "mr": s[5]
            }
        })

    shandilya_list = []
    for s in SHANDILYA_SUTRAS:
        shandilya_list.append({
            "sutra_no": str(s[0]),
            "sanskrit": s[1],
            "theme": s[2],
            "initial_meaning": {
                "en": s[3],
                "hi": s[4],
                "mr": s[5]
            }
        })

    with open(RAW_DIR / "narada_bhakti_sutra.json", "w", encoding="utf-8") as f:
        json.dump(narada_list, f, ensure_ascii=False, indent=2)

    with open(RAW_DIR / "shandilya_bhakti_sutra.json", "w", encoding="utf-8") as f:
        json.dump(shandilya_list, f, ensure_ascii=False, indent=2)

    print(f"Successfully populated {len(narada_list)} Narada Sutras into data/raw/narada_bhakti_sutra.json")
    print(f"Successfully populated {len(shandilya_list)} Shandilya Sutras into data/raw/shandilya_bhakti_sutra.json")


if __name__ == "__main__":
    main()
